solution.solution.c:
#include <limits.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

bool add_int(int a, int b, int *out)
{
    if ((b > 0 && a > INT_MAX - b) || (b < 0 && a < INT_MIN - b)) return false;
    *out = a + b;
    return true;
}

bool mul_int(int a, int b, int *out)
{
    if (a == 0 || b == 0) { *out = 0; return true; }
    if (a > 0) {
        if (b > 0 ? a > INT_MAX / b : b < INT_MIN / a) return false;
    } else {
        if (b > 0 ? a < INT_MIN / b : (a != 0 && b < INT_MAX / a)) return false;
    }
    *out = a * b;
    return true;
}

bool mul_size(size_t a, size_t b, size_t *out)
{
    if (a != 0 && b > SIZE_MAX / a) return false;
    *out = a * b;
    return true;
}

unitTests:
TEST("additions") { int r = 7; CHECK(add_int(2, 3, &r)); CHECK_EQ(r, 5); CHECK(add_int(INT_MAX - 1, 1, &r)); CHECK_EQ(r, INT_MAX); r = 7; CHECK(!add_int(INT_MAX, 1, &r)); CHECK(!add_int(INT_MIN, -1, &r)); CHECK_EQ(r, 7); CHECK(add_int(INT_MIN, INT_MAX, &r)); CHECK_EQ(r, -1); }
TEST("multiplications") { int r = 7; CHECK(mul_int(46340, 46340, &r)); CHECK_EQ(r, 2147395600); CHECK(!mul_int(46341, 46341, &r)); CHECK(!mul_int(-1, INT_MIN, &r)); CHECK(!mul_int(INT_MIN, -1, &r)); CHECK(mul_int(-1, INT_MAX, &r)); CHECK_EQ(r, -INT_MAX); CHECK(mul_int(0, INT_MIN, &r)); CHECK_EQ(r, 0); CHECK(!mul_int(-65536, 65536, &r)); CHECK(mul_int(-32768, 65536, &r)); CHECK_EQ(r, INT_MIN); }
TEST("sizes") { size_t s = 3; CHECK(mul_size(1000, 1000, &s)); CHECK_EQ((int)s, 1000000); s = 3; CHECK(!mul_size(SIZE_MAX / 2, 3, &s)); CHECK_EQ((int)s, 3); CHECK(mul_size(0, SIZE_MAX, &s)); CHECK_EQ((int)s, 0); }

